// ============================================================================
// src/lib/tools/openssl-s-client-explainer/captures.ts
// ----------------------------------------------------------------------------
// REAL s_client OUTPUT for the golden vectors. OpenSSL 3.5 is the long-term-
// support release (supported until 2030-04-08, openssl-library.org/policies/
// releasestrat, read 2026-10-27).
// RUNS: OpenSSL 3.5.9 (29 Sep 2026), the long-term-support release, built in this sandbox on 2026-10-27 from
// the official source tarball (SHA-256 603f5602e2eef00d77fbd429d34dcd5822bb301757a1bc9cdb24c670f1eb859a as
// published, good signature by the OpenSSL release key B146 647E 45A7 B339 47AB 226B 2A2C 87D1 6169 2D40),
// client and servers alike: s_client against openssl s_server on localhost, with a throwaway test CA made
// that day (root, intermediate, RSA 2048 and EC P-256 server certificates for www.example.test, a
// self-signed one, an OCSP response); every private key was deleted after the runs.
// stdout and stderr together, byte for byte, as 2>&1 writes them; stdin was held
// open one second, then closed. Two things a 3.5.9 pair shows that the earlier
// set (3.0.13 runs rewritten into this layout) could not: under TLS 1.3 the
// group negotiated is X25519MLKEM768 and s_client prints "Negotiated TLS1.3
// group:" instead of a temp key line, and the ClientHello carries that group's
// key share (the -msg capture, back in the set). The Master-Key and Resumption
// PSK values are the secrets of throwaway localhost sessions, kept because they
// are what secretsPrinted is about. No private key is in this file.
// ============================================================================

import { EXAMPLE_COMMAND, EXAMPLE_OUTPUT } from "./example"; // the Example button's capture, shared with the page

/** One capture: a real run. */
export interface Capture {
  id: string; // stable id
  layout: string; // the openssl version whose layout the output is in
  run: string; // the openssl version that made the run (the same: these are real runs)
  scenario: string; // what the capture shows
  command: string; // the command line, as typed
  output: string; // what it printed
}

/** Every capture, in the order the vectors use them. */
